-- ============================================================================
-- Seed des points de programme de 1re SPÉCIALITÉ (programme de spécialité de
-- mathématiques de première, voie générale) + RÉFÉRENCES d'automatismes
-- + correction E1 des Exemples d'algorithme de 2de.
-- ============================================================================
-- Source de vérité : docs/wip/arbre-notions/seed-1spe.md (VALIDÉ INTÉGRALEMENT par
-- David le 2026-10-08 : scissions, discutables, S1, V2, E1, V1) ; fichier GÉNÉRÉ —
-- ne pas éditer à la main. Aucun changement d'arbre.
--   * 165 points, codes 1SPE-201…1SPE-365, grade '1_SPE' (l'ancien seed
--     1SPE-001…173, grade NULL, reste intact jusqu'à C5) ; 17 algorithme,
--     12 démonstration, 29 approfondissement (17 approfondissements + 12 exemples
--     d'algorithme, E1).
--   * 93 références du grade '1_SPE' : lignes propres de la 1re, liste de 2de
--     reprise (C16), entretien du vocabulaire de 2de (V1) ; 1 auto-référence.
--   * E1 : les 10 Exemples d'algorithme de 2de passent de 'attendu' à
--     'approfondissement' (décision David du 2026-08-29, confirmée le 2026-10-08).
--
-- MIGRATION ADDITIVE (aucune ligne supprimée ; un UPDATE d'exigence sur 10 points
-- de 2de, sans perte). Rollback (⚠️ scopé) :
--   delete from public.curriculum_point_automatismes where grade = '1_SPE';
--   delete from public.curriculum_points where grade = '1_SPE';
--   update public.curriculum_points set exigence = 'attendu'
--    where grade = '2' and code in ('2-241', '2-242', '2-257', '2-283', '2-321', '2-322', '2-361', '2-362', '2-387', '2-388');
-- ⚠️ Ce rollback n'est anodin que tant qu'AUCUN usage ne s'accroche à ces
-- points. Supprimer un point efface EN SILENCE (ON DELETE CASCADE) : le suivi
-- élève (student_point_state), les rattachements d'exercices du prof
-- (exercise_curriculum_points), journal_entry_points, srs_anti_fraud_flags, et
-- les références d'automatismes d'AUTRES grades (Tle…) qui viseraient ces
-- points ; question_template_points (ON DELETE RESTRICT) fait échouer le
-- rollback. Dès qu'un usage existe : DESTRUCTIF (données d'élèves mineurs) —
-- arrêt obligatoire et accord explicite de David (règle CLAUDE.md).
-- ============================================================================

-- ---- 1. E1 : Exemples d'algorithme de 2de → approfondissement ---------------

do $e1$
declare n integer;
begin
	update public.curriculum_points set exigence = 'approfondissement'
	 where grade = '2' and kind = 'algorithme' and exigence = 'attendu'
	   and code in ('2-241', '2-242', '2-257', '2-283', '2-321', '2-322', '2-361', '2-362', '2-387', '2-388');
	get diagnostics n = row_count;
	if n <> 10 then raise exception 'E1 : % ligne(s) au lieu de 10', n; end if;
end $e1$;

