-- ---- 4. Vérifications (la migration échoue si le compte n'y est pas) --------

do $check$
declare
	v_pts integer; v_sans_noeud integer; v_refs integer; v_auto integer;
	v_algo integer; v_demo integer; v_appro integer; v_regime integer;
	v_anciens integer; v_e1 integer; v_2de_algo_attendu integer;
begin
	select count(*) into v_pts from public.curriculum_points where grade = '1_SPE';
	select count(*) into v_sans_noeud from public.curriculum_points where grade = '1_SPE' and node_id is null;
	select count(*) into v_refs from public.curriculum_point_automatismes where grade = '1_SPE';
	select count(*) into v_auto from public.curriculum_point_automatismes a
	  join public.curriculum_points p on p.id = a.point_id
	 where a.grade = '1_SPE' and p.grade = '1_SPE';
	select count(*) into v_algo from public.curriculum_points where grade = '1_SPE' and kind = 'algorithme';
	select count(*) into v_demo from public.curriculum_points where grade = '1_SPE' and kind = 'demonstration';
	select count(*) into v_appro from public.curriculum_points where grade = '1_SPE' and exigence = 'approfondissement';
	select count(*) into v_regime from public.curriculum_points where grade = '1_SPE' and regime_acquisition <> 'diversite';
	-- L'ancien seed (grade NULL, rattaché aux objectifs) est intact.
	select count(*) into v_anciens from public.curriculum_points
	 where code ~ '^1SPE-(0\d\d|1[0-6]\d|17[0-3])$' and grade is null and objective_id is not null;
	-- E1 : en 2de, seuls les 17 points du bloc Algorithmique restent 'attendu'.
	select count(*) into v_e1 from public.curriculum_points
	 where grade = '2' and kind = 'algorithme' and exigence = 'approfondissement';
	select count(*) into v_2de_algo_attendu from public.curriculum_points
	 where grade = '2' and kind = 'algorithme' and exigence = 'attendu';
	if v_pts <> 165 or v_sans_noeud <> 0 or v_refs <> 93 or v_auto <> 1
	   or v_algo <> 17 or v_demo <> 12 or v_appro <> 29 or v_regime <> 0
	   or v_anciens <> 173 or v_e1 <> 10 or v_2de_algo_attendu <> 17 then
		raise exception 'seed 1re spé incohérent : points=%, sans nœud=%, réfs=%, auto=%, algo=%, dém=%, appro=%, non-diversité=%, anciens=%, E1=%, algo 2de attendus=%',
			v_pts, v_sans_noeud, v_refs, v_auto, v_algo, v_demo, v_appro, v_regime, v_anciens, v_e1, v_2de_algo_attendu;
	end if;
end $check$;
